master.css:
/* ============================================================================
   TOKENS — "Ridgeline" design system
   Homebuyer's Playbook · Mountain State Financial Group

   Per SLIDE_DESIGN_SPEC.md. Two backgrounds deck-wide (Deep Forest + White/Mist),
   one green accent moment per slide, Montserrat + Open Sans, 1920×1080 canvas,
   squared geometry, NO emoji, NO decorative shadows.

   The green (#8cc63E) is an ACCENT and never body text or a full-slide
   background — there is deliberately no green text token below.
   ========================================================================= */

:root {
  /* ---- Palette (the whole deck lives in these) ------------------------ */
  --forest:      #0C3335;  /* primary dark canvas · photo wash · dark panels */
  --forest-mid:  #14494B;  /* secondary dark block · hover / active step */
  --sage:        #4b7b4d;  /* eyebrow labels on light · secondary rules */
  --green:       #8cc63E;  /* THE accent — one moment per slide */
  --charcoal:    #404041;  /* body copy on light */
  --mist:        #F5F7F4;  /* light neutral background */
  --white:       #FFFFFF;
  --red:         #C0392B;  /* DON'T on the Do/Don't handout slides only */
  --do-green:    #3E8E41;  /* DO on the handout — readable green */

  /* ---- Text ----------------------------------------------------------- */
  --text-on-light:        var(--charcoal);
  --text-head-light:      var(--forest);
  --text-on-dark:         var(--white);
  --text-body-dark:       rgba(255,255,255,0.82);
  --text-meta-dark:       rgba(255,255,255,0.62);
  --text-meta-light:      #6A7370;

  /* ---- Backgrounds — exactly two families ----------------------------- */
  --bg-dark:   var(--forest);
  --bg-light:  var(--mist);
  --bg-white:  var(--white);

  /* Cards */
  --card-on-dark:   rgba(255,255,255,0.07);
  --card-on-dark-h: rgba(255,255,255,0.12);
  --card-on-light:  var(--white);
  --card-border-light: #E2E7E2;

  /* Diagram bands — an on-palette forest→green ramp for the one or two
     diagrams the deck keeps (payment makeup, process). No numbers ride these. */
  --band-1: var(--green);
  --band-2: #6FA847;
  --band-3: var(--sage);
  --band-4: var(--forest-mid);
  --band-5: var(--forest);

  /* Payment-makeup semantic bands (proportional only, always labelled) */
  --pay-principal: var(--forest);
  --pay-interest:  var(--forest-mid);
  --pay-taxes:     var(--sage);
  --pay-insurance: #8FA69B;
  --pay-mi:        var(--green);
  --pay-hoa:       var(--charcoal);

  /* ---- Type ----------------------------------------------------------
     Montserrat display, Open Sans body. Sizes are the spec's px values on
     the 1920×1080 canvas (authored 1:1, then the canvas scales to fit).    */
  --font-display: 'Montserrat', 'Helvetica Neue', Arial, sans-serif;
  --font-body:    'Open Sans', 'Helvetica Neue', Arial, sans-serif;

  --fs-title:      132px;  /* title slide headline  (900) */
  --fs-section:    80px;   /* section headline      (800) */
  --fs-headline:   72px;   /* content headline      (800) */
  --fs-card-title: 42px;   /* card / item title     (700–800) */
  --fs-card-title-s: 34px; /* dense grids */
  --fs-stat:       72px;   /* big stat number       (900) */
  --fs-eyebrow:    23px;   /* ALL CAPS label        (700) */
  --fs-body:       30px;   /* body copy             (400) */
  --fs-body-s:     26px;   /* dense body — the 26px floor for content */
  --fs-footer:     18px;   /* footer / legal        (400) — reduced per client */
  --fs-min:        21px;   /* HARD FLOOR — nothing below this, anywhere */

  --ls-title:  -0.035em;
  --ls-head:   -0.02em;
  --ls-eyebrow: 0.22em;

  --lh-title:  0.9;
  --lh-head:   1.0;
  --lh-body:   1.45;

  --fw-body:      400;
  --fw-body-semi: 600;
  --fw-700: 700;
  --fw-800: 800;
  --fw-900: 900;

  /* ---- Geometry ------------------------------------------------------- */
  --slide-w: 1920px;
  --slide-h: 1080px;
  --pad-y: 90px;
  --pad-x: 96px;

  --gap-card:    28px;   /* 26–36 */
  --gap-section: 60px;   /* 56–64 */
  --card-pad:    40px;   /* 44–52 */

  --radius: 0px;         /* squared. inner elements ≤4px, prefer 0 */
  --accent-bar-w: 96px;
  --accent-bar-h: 8px;

  /* The only permitted shadow: headline over photography. */
  --shadow-head: 0 4px 40px rgba(0,0,0,0.35);

  /* Photo legibility washes (§5) */
  --wash-vertical: linear-gradient(180deg,
      rgba(12,51,53,0.86) 0%, rgba(12,51,53,0.55) 45%, rgba(12,51,53,0.95) 100%);
  --wash-horizontal: linear-gradient(90deg,
      rgba(12,51,53,0.35), rgba(12,51,53,0.85));

  /* ---- Motion --------------------------------------------------------- */
  --ease-out: cubic-bezier(.16, .84, .44, 1);
  --dur-fast: 200ms;
  --dur-base: 260ms;
  --stagger:  60ms;
}

@media (prefers-reduced-motion: reduce) {
  :root { --dur-fast: 1ms; --dur-base: 1ms; --stagger: 0ms; }
  *, *::before, *::after {
    animation-duration: 1ms !important;
    transition-duration: 1ms !important;
  }
}

/* ============================================================================
   BASE — reset, the 1920×1080 stage, footer/compliance, photo placeholders
   ========================================================================= */

*, *::before, *::after { box-sizing: border-box; }

html, body {
  margin: 0; padding: 0; height: 100%;
  background: #000;
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body { font-variant-numeric: tabular-nums; }

h1,h2,h3,h4,p,ul,ol,dl,dd,figure,blockquote { margin: 0; }
ul, ol { padding: 0; list-style: none; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
img, svg { display: block; max-width: 100%; }
em, i { font-style: normal; font-weight: var(--fw-800); }

:focus-visible { outline: 3px solid var(--green); outline-offset: 3px; }

.visually-hidden {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

/* ---------------------------------------------------------------------------
   STAGE — fixed 1920×1080 canvas, scaled to fit the viewport.
   Authoring at native size keeps the spec's px = the rendered px, so the
   "nothing below 21px" floor is a real guarantee.
   ------------------------------------------------------------------------ */
.stage { position: fixed; inset: 0; background: #000; overflow: hidden; }
.slide-fit-shell { position: absolute; overflow: visible; }
.slide-scaler {
  position: absolute;
  inset: 0 auto auto 0;
  width: var(--slide-w);
  height: var(--slide-h);
  transform-origin: top left;
}

.slide {
  position: absolute; inset: 0;
  display: none;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background: var(--bg-light);
  color: var(--text-on-light);
  font-family: var(--font-body);
  font-size: var(--fs-body);
  line-height: var(--lh-body);
  overflow: hidden;
}
.slide.is-active { display: flex; }

.slide[data-bg="dark"]  { background: var(--bg-dark);  color: var(--text-body-dark); }
.slide[data-bg="white"] { background: var(--bg-white); color: var(--text-on-light); }
.slide[data-bg="mist"]  { background: var(--bg-light); color: var(--text-on-light); }

/* Full-bleed slides let the photo/wash reach the edges; text keeps the gutter */
.slide[data-bleed] { padding: 0; }

/* ---------------------------------------------------------------------------
   EYEBROW + HEADLINE + ACCENT BAR
   ------------------------------------------------------------------------ */
.eyebrow {
  font-family: var(--font-display);
  font-weight: var(--fw-700);
  font-size: var(--fs-eyebrow);
  letter-spacing: var(--ls-eyebrow);
  text-transform: uppercase;
  color: var(--sage);
}
.slide[data-bg="dark"] .eyebrow { color: var(--green); }

.accent-bar {
  width: var(--accent-bar-w); height: var(--accent-bar-h);
  background: var(--green);
  flex: none;
}

.headline {
  font-family: var(--font-display);
  font-weight: var(--fw-800);
  font-size: var(--fs-headline);
  line-height: var(--lh-head);
  letter-spacing: var(--ls-head);
  color: var(--text-head-light);
  text-wrap: balance;
}
.slide[data-bg="dark"] .headline { color: var(--white); }
.headline.is-long { font-size: 60px; }

.subhead {
  font-family: var(--font-body);
  font-size: var(--fs-body);
  color: var(--text-meta-light);
  text-wrap: pretty;
  max-width: 1100px;
}
.slide[data-bg="dark"] .subhead { color: var(--text-body-dark); }

/* Standard content header block: eyebrow · headline · accent bar */
.slide-header { flex: none; margin-bottom: 44px; }
.slide-header .eyebrow { display: block; margin-bottom: 18px; }
.slide-header .accent-bar { margin-top: 22px; }

.slide-body { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }

/* Body paragraphs cap their measure — never a full 1728px line. */
.measure { max-width: 900px; }

/* ---------------------------------------------------------------------------
   PHOTOGRAPHY — full-bleed within container, always washed, drop-placeholders
   where an image isn't supplied yet (labeled, never a silent gray box).
   ------------------------------------------------------------------------ */
.photo {
  position: absolute; inset: 0;
  overflow: hidden;
  background: var(--forest);
}
.photo img { width: 100%; height: 100%; object-fit: cover; }
.photo .wash { position: absolute; inset: 0; pointer-events: none; }
.photo .wash[data-dir="v"] { background: var(--wash-vertical); }
.photo .wash[data-dir="h"] { background: var(--wash-horizontal); }

.photo-placeholder {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  background:
    repeating-linear-gradient(-45deg,
      rgba(255,255,255,0.03) 0 22px, rgba(255,255,255,0.06) 22px 44px),
    var(--forest);
}
.photo-placeholder span {
  font-family: var(--font-display);
  font-weight: var(--fw-700);
  font-size: 26px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.5);
  border: 2px dashed rgba(255,255,255,0.35);
  padding: 16px 30px;
  text-align: center;
  max-width: 70%;
}

/* ---------------------------------------------------------------------------
   FOOTER + COMPLIANCE (§6)
   Logo sits on a white plate on dark backgrounds. NMLS + license lines right.
   Rendered from data so it can't be forgotten.
   ------------------------------------------------------------------------ */
.slide-footer {
  position: absolute;
  left: var(--pad-x); right: var(--pad-x); bottom: 46px;
  display: flex; align-items: center; justify-content: space-between; gap: 30px;
  padding-top: 26px;
  border-top: 2px solid rgba(255,255,255,0.18);
  z-index: 3;
}
.slide[data-bg="white"] .slide-footer,
.slide[data-bg="mist"] .slide-footer { border-top-color: rgba(12,51,53,0.16); }

/* Logo sits directly on the background — vector, no plate. Larger. */
.footer-logo { flex: none; display: flex; align-items: center; }
.footer-logo img { height: 68px; width: auto; }

/* Slide 1's knockout logo keeps a stable safe area on every screen size. */
#slide-opening .footer-logo { width: 300px; max-width: 100%; }
#slide-opening .footer-logo img {
  width: 100%; height: auto; max-height: 68px;
  object-fit: contain; object-position: left center;
}

.footer-meta {
  min-width: 0;
  display: flex; align-items: center; justify-content: flex-end; gap: 18px;
}

.footer-lines {
  text-align: right;
  font-family: var(--font-body);
  font-size: var(--fs-footer);
  line-height: 1.45;
  color: var(--text-meta-dark);
}
.slide[data-bg="white"] .footer-lines,
.slide[data-bg="mist"] .footer-lines { color: var(--text-meta-light); }

.equal-housing-logo {
  flex: none;
  width: auto; height: 64px;
  background: var(--white);
}

/* Hypothetical / results disclaimer — italic, 21px */
.disclaimer {
  position: absolute;
  left: var(--pad-x); right: var(--pad-x); bottom: 150px;
  font-family: var(--font-body);
  font-style: italic;
  font-size: var(--fs-min);
  color: var(--text-meta-dark);
  z-index: 3;
}
.slide[data-bg="white"] .disclaimer,
.slide[data-bg="mist"] .disclaimer { color: var(--text-meta-light); }

/* When footer OR disclaimer is present, reserve their space. */
.slide[data-footer] { padding-bottom: 150px; }
.slide[data-footer][data-disclaimer] { padding-bottom: 196px; }

/* Placeholder chips for contact/link fields not yet supplied */
.ph {
  display: inline-flex; align-items: center;
  padding: 2px 14px;
  border: 2px dashed var(--green);
  color: inherit;
  font-family: var(--font-display);
  font-weight: var(--fw-700);
  font-size: 22px;
  letter-spacing: 0.08em;
}

/* ---------------------------------------------------------------------------
   BUILD ANIMATION
   ------------------------------------------------------------------------ */
.build { opacity: 0; transform: translateY(16px);
  transition: opacity var(--dur-base) var(--ease-out),
              transform var(--dur-base) var(--ease-out); }
.slide.is-active .build.is-in { opacity: 1; transform: none; }

/* ---------------------------------------------------------------------------
   NAV + PROGRESS
   ------------------------------------------------------------------------ */
.deck-progress {
  position: fixed; top: 0; left: 0; height: 4px;
  background: var(--green); z-index: 45;
  transition: width var(--dur-base) var(--ease-out);
}
.deck-nav {
  position: fixed; bottom: 18px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 14px;
  padding: 8px 14px;
  background: rgba(12,51,53,0.9);
  border: 1px solid rgba(255,255,255,0.16);
  z-index: 40; opacity: 0;
  transition: opacity var(--dur-base) var(--ease-out);
}
.deck-nav-hidden .deck-nav { display: none; }
.deck-nav:hover, .deck-nav:focus-within, body.nav-visible .deck-nav { opacity: 1; }
.deck-nav button {
  width: 34px; height: 34px; display: grid; place-items: center;
  color: rgba(255,255,255,0.9); font-size: 16px;
}
.deck-nav button:hover { background: rgba(255,255,255,0.14); }
.deck-nav .nav-count {
  font-family: var(--font-display); font-size: 14px; letter-spacing: 0.06em;
  color: rgba(255,255,255,0.75); padding: 0 6px; min-width: 70px; text-align: center;
}

/* ---------------------------------------------------------------------------
   ANNOTATION overlay + toolbar
   ------------------------------------------------------------------------ */
/* Above the modal (z 100) so you can draw over popouts too. Off = no pointer
   events, so popouts stay interactive; On = captures the whole screen. */
#annotate-layer { position: fixed; inset: 0; z-index: 200; pointer-events: none; }
#annotate-layer.is-on { pointer-events: auto; cursor: crosshair; }
#annotate-layer svg { width: 100%; height: 100%; overflow: visible; }
.annotate-text {
  position: absolute; min-width: 24px; min-height: 42px; padding: 2px 4px;
  font-family: var(--font-display); font-weight: 700; font-size: 34px;
  outline: none; white-space: nowrap; caret-color: currentColor;
  text-shadow: 0 2px 10px rgba(0,0,0,.35);
}
.annotate-text:empty::before { content: "Type…"; opacity: .5; }
/* Fluorescent laser dot with a bright core + glowing halo in the current colour. */
.laser-dot { position: fixed; width: 18px; height: 18px; border-radius: 50%;
  transform: translate(-50%, -50%); pointer-events: none;
  background: var(--laser, #FF1744);
  box-shadow: 0 0 6px 2px #fff, 0 0 20px 8px var(--laser, #FF1744), 0 0 40px 16px var(--laser, #FF1744);
}

#annotate-bar {
  position: fixed; bottom: 74px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 6px; padding: 8px 10px; z-index: 210;
  background: rgba(12,51,53,.95); border: 1px solid rgba(255,255,255,.16);
}
#annotate-bar[hidden] { display: none; }

/* Transient hint (e.g. when a remote fullscreen request is blocked) */
#deck-toast {
  position: fixed; bottom: 78px; left: 50%; transform: translateX(-50%) translateY(8px);
  background: rgba(12,51,53,.96); color: #fff; border: 1px solid rgba(255,255,255,.16);
  font-family: var(--font-display); font-weight: 700; font-size: 16px;
  padding: 12px 20px; z-index: 220; opacity: 0; pointer-events: none;
  transition: opacity var(--dur-base) var(--ease-out), transform var(--dur-base) var(--ease-out);
}
#deck-toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
#annotate-bar button {
  min-width: 40px; height: 40px; padding: 0 10px; color: #fff;
  font-family: var(--font-display); font-weight: 700; font-size: 18px;
  border: 1px solid transparent;
}
#annotate-bar button:hover { background: rgba(255,255,255,.12); }
#annotate-bar button.is-active { background: var(--green); color: var(--forest); }
#annotate-bar button.col { width: 30px; min-width: 30px; height: 30px; padding: 0; border: 2px solid rgba(255,255,255,.4); }
#annotate-bar button.col.is-active { border-color: #fff; }
#annotate-bar .sep { width: 1px; height: 26px; background: rgba(255,255,255,.2); margin: 0 4px; }

/* Preview iframe (mini next-slide in presenter view): hide chrome */
body.is-preview .deck-nav, body.is-preview .deck-progress { display: none; }
body.is-preview { pointer-events: none; }

/* Dev guide: webcam/safe visualization off by default */
body.show-guides .slide::after {
  content: ""; position: absolute; top: 0; right: 0;
  width: 460px; height: 300px;
  outline: 2px dashed rgba(140,198,62,0.6); pointer-events: none; z-index: 2;
}

/* ============================================================================
   COMPONENTS — the card and the modal, plus the layout atoms.
   Softly rounded geometry, no emoji. Cards carry an 8px accent edge and a
   quiet shadow for depth (matches the popout language).
   ========================================================================= */

/* ---------------------------------------------------------------------------
   CARD  (opens a popout)
   ------------------------------------------------------------------------ */
.card {
  position: relative;
  display: flex; flex-direction: column; gap: 14px;
  padding: var(--card-pad);
  text-align: left;
  background: var(--card-on-light);
  border: 1px solid var(--card-border-light);
  border-left: 8px solid var(--forest);
  color: var(--text-head-light);
  border-radius: 18px;
  box-shadow: 0 4px 16px rgba(12,51,53,0.06);
  transition: transform var(--dur-fast) var(--ease-out),
              box-shadow var(--dur-fast) var(--ease-out),
              border-color var(--dur-fast) var(--ease-out),
              background var(--dur-fast) var(--ease-out);
}
.card:hover, .card:focus-visible {
  transform: translateY(-3px); border-left-color: var(--green);
  box-shadow: 0 12px 30px rgba(12,51,53,0.12);
}

.card--accent-sage  { border-left-color: var(--sage); }
.card--accent-green { border-left-color: var(--green); }

.card-title {
  font-family: var(--font-display);
  font-weight: var(--fw-800);
  font-size: var(--fs-card-title);
  line-height: 1.1;
  letter-spacing: -0.01em;
  color: var(--text-head-light);
  text-wrap: balance;
}
.card-meta { font-family: var(--font-body); font-size: var(--fs-body-s);
  line-height: 1.35; color: var(--text-on-light); }
.card-stat {
  margin-top: auto;
  font-family: var(--font-display); font-weight: var(--fw-900);
  font-size: 46px; color: var(--forest);
}
.card--accent-green .card-stat { color: var(--sage); }

/* "Open" affordance — a green corner tick, no icon font, no emoji */
.card-open {
  position: absolute; top: 22px; right: 22px;
  width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%;
  font-family: var(--font-display); font-weight: var(--fw-800); font-size: 22px;
  color: var(--forest); background: var(--mist);
}
.card:hover .card-open { background: var(--green); color: var(--forest); }

/* Dense grids (8-up players / steps) */
.card--dense { padding: 30px; gap: 8px; }
.card--dense .card-title { font-size: var(--fs-card-title-s); }
.card--dense .card-open { width: 28px; height: 28px; font-size: 18px; top: 16px; right: 16px; }

/* Quote-style cards (assumptions) read like thoughts */
.card--quote .card-title {
  font-family: var(--font-body); font-weight: var(--fw-body-semi);
  font-size: 32px; line-height: 1.3; color: var(--charcoal);
}

/* Accordion row (questions) */
.card--row { flex-direction: row; align-items: center; gap: 30px; padding: 30px 40px; }
.card--row .card-index {
  flex: none; width: 60px; height: 60px; display: grid; place-items: center; border-radius: 50%;
  background: var(--green); color: var(--forest);
  font-family: var(--font-display); font-weight: var(--fw-900); font-size: 30px;
}
.card--row .card-title { flex: 1 1 auto; font-size: 36px; }

/* Cards on dark slides */
.slide[data-bg="dark"] .card {
  background: var(--card-on-dark); border-color: transparent;
  border-left-color: var(--green); color: var(--white);
}
.slide[data-bg="dark"] .card:hover { background: var(--card-on-dark-h); }
.slide[data-bg="dark"] .card-title { color: var(--white); }
.slide[data-bg="dark"] .card-meta { color: var(--text-body-dark); }
.slide[data-bg="dark"] .card-stat { color: var(--green); }
.slide[data-bg="dark"] .card-open { background: rgba(255,255,255,0.12); color: var(--white); }

/* Grids */
.card-grid { display: grid; gap: var(--gap-card); align-content: start; }
.card-grid[data-cols="2"] { grid-template-columns: repeat(2, 1fr); }
.card-grid[data-cols="3"] { grid-template-columns: repeat(3, 1fr); }
.card-grid[data-cols="4"] { grid-template-columns: repeat(4, 1fr); }
.row-stack { display: flex; flex-direction: column; gap: 18px; }

/* ---------------------------------------------------------------------------
   MODAL  (popout) — fixed authored surface with compact title strip
   ------------------------------------------------------------------------ */
.modal-root { position: fixed; inset: 0; z-index: 100; display: none; overflow: hidden; }
.modal-root.is-open { display: block; }
.modal-root.is-measuring .modal-shell { visibility: hidden; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(12,51,53,0.72);
  opacity: 0; transition: opacity var(--dur-fast) var(--ease-out); }
.modal-root.is-visible .modal-backdrop { opacity: 1; }
.modal-shell {
  position: fixed; overflow: visible; opacity: 0;
  transition: opacity var(--dur-fast) var(--ease-out);
}
.modal-root.is-visible .modal-shell { opacity: 1; }

.modal {
  position: relative; width: 1200px; height: auto;
  display: flex; flex-direction: column;
  background: var(--white); border-radius: 22px;
  box-shadow: 0 44px 100px rgba(8,28,29,0.50), 0 4px 14px rgba(8,28,29,0.24);
  overflow: hidden; transform-origin: top left; transition: none;
}

/* drag handle = the header */
.modal-head {
  height: 60px; flex: none; display: flex; align-items: center;
  padding: 8px 68px 8px 30px;
  background: var(--forest); color: var(--white);
  box-shadow: inset 0 -3px 0 var(--green);
  cursor: grab; touch-action: none;
}
.modal-head:active { cursor: grabbing; }

/* resize handle, bottom-right — a soft, unobtrusive grip */
.modal-resize {
  position: absolute; right: 8px; bottom: 8px; width: 20px; height: 20px;
  padding: 0; border: 0; cursor: nwse-resize; touch-action: none; opacity: 0.5;
  border-radius: 3px;
  background:
    radial-gradient(circle 2px at 14px 14px, var(--sage) 99%, transparent),
    radial-gradient(circle 2px at 14px 7px, var(--sage) 99%, transparent),
    radial-gradient(circle 2px at 7px 14px, var(--sage) 99%, transparent);
}
.modal-resize:hover { opacity: 0.9; }
.modal-title {
  min-width: 0; overflow: hidden;
  font-family: var(--font-display); font-weight: var(--fw-800);
  color: var(--white); font-size: 22px; line-height: 1;
  text-overflow: ellipsis; white-space: nowrap;
}

.modal-close {
  position: absolute; z-index: 1; top: 13px; right: 16px; width: 36px; height: 36px;
  display: grid; place-items: center; border-radius: 50%;
  background: rgba(255,255,255,0.14); color: var(--white);
  font-family: var(--font-display); font-size: 18px;
  transition: background var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out);
}
.modal-close:hover { background: var(--green); color: var(--forest); }

.modal-body { flex: none; overflow: visible; padding: 46px 56px 50px;
  font-family: var(--font-body); font-size: 28px; line-height: 1.5; color: var(--charcoal);
}

.modal--media .modal-head {
  height: 52px; flex: none; display: flex; align-items: center;
  padding: 8px 64px 8px 18px;
}
.modal--media .modal-foot { display: none; }
.modal--media .modal-title { font-size: 20px; line-height: 1; }
.modal--media .modal-body {
  flex: 1 1 auto; min-height: 0; padding: 0; overflow: hidden;
  position: relative; background: var(--white);
}
.modal-media-frame { width: 100%; height: 100%; display: grid; place-items: center; }
.modal-media-frame img { width: 100%; height: 100%; object-fit: contain; user-select: none; }
.modal-media-error {
  font-family: var(--font-display); font-size: 32px;
  font-weight: var(--fw-700); color: var(--forest);
}

.modal-section + .modal-section { margin-top: 22px; }
/* Toned pros/cons sections read as soft cards, not hard blocks. */
.modal-section[data-tone] { padding: 26px 32px; border-radius: 16px; }
.modal-section[data-tone="pros"] { background: #F3F8EC; }
.modal-section[data-tone="cons"] { background: #FAF3F1; }
.modal-section-head {
  font-family: var(--font-display); font-weight: var(--fw-800);
  font-size: 22px; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--forest); margin-bottom: 16px;
  display: flex; align-items: center; gap: 14px;
}
.modal-section[data-tone="pros"] .modal-section-head { color: var(--sage); }
.modal-section[data-tone="cons"] .modal-section-head { color: #B23A2E; }
.modal-section[data-tone] .modal-section-head::before {
  display: inline-grid; place-items: center; width: 32px; height: 32px;
  border-radius: 50%; font-size: 22px; line-height: 1; flex: none;
}
.modal-section[data-tone="pros"] .modal-section-head::before { content: "+"; background: rgba(140,198,62,0.20); color: var(--sage); }
.modal-section[data-tone="cons"] .modal-section-head::before { content: "–"; background: rgba(178,58,46,0.14); color: #B23A2E; }

.modal-list > li { position: relative; padding-left: 32px; margin-bottom: 14px; }
.modal-list > li::before { content: ""; position: absolute; left: 0; top: 15px;
  width: 10px; height: 10px; border-radius: 50%; background: var(--green); }
.modal-section[data-tone="cons"] .modal-list > li::before { background: #B23A2E; }
.modal-list > li strong { color: var(--forest); font-weight: var(--fw-800); }

.modal-note { margin-top: 18px; padding: 20px 26px; border-radius: 12px;
  border-left: 6px solid var(--green); background: var(--mist); }

.modal-foot { flex: none; padding: 22px 56px; border-top: 2px solid var(--card-border-light);
  font-family: var(--font-body); font-size: var(--fs-min); font-style: italic; color: var(--text-meta-light); }

.modal-intro { font-size: 26px; color: var(--charcoal); margin-bottom: 24px; }

/* Comparison table (loan compare popout) */
.modal-table-wrap { overflow: hidden; margin-bottom: 8px; border-radius: 14px;
  border: 1px solid var(--card-border-light); }
.modal-table { width: 100%; border-collapse: collapse; font-family: var(--font-body); }
.modal-table th, .modal-table td { text-align: left; padding: 16px 20px; font-size: 23px;
  border-bottom: 1px solid var(--card-border-light); }
.modal-table thead th { font-family: var(--font-display); font-weight: var(--fw-800);
  font-size: 26px; color: var(--white); background: var(--forest); border-bottom: 0; }
.modal-table thead th:first-child { background: var(--forest); }
.modal-table tbody th { font-family: var(--font-display); font-weight: var(--fw-700);
  color: var(--forest); font-size: 22px; }
.modal-table td { color: var(--charcoal); }
.modal-table tbody tr:nth-child(odd) td, .modal-table tbody tr:nth-child(odd) th { background: var(--mist); }
.modal-table td strong { color: var(--forest); }

/* ---------------------------------------------------------------------------
   LAYOUT ATOMS
   ------------------------------------------------------------------------ */

/* Split 860/1060 (§4.2) */
.split { display: grid; flex: 1 1 auto; min-height: 0; }
.split[data-ratio="photo-left"]  { grid-template-columns: 860px 1fr; }
.split[data-ratio="photo-right"] { grid-template-columns: 1fr 860px; }
.split[data-ratio="1-1"] { grid-template-columns: 1fr 1fr; gap: var(--gap-section); align-items: center; }
.split-copy { display: flex; flex-direction: column; justify-content: center;
  padding: 0; min-width: 0; }
.split-photo { position: relative; min-width: 0; }

/* Two-panel compare (§4.4) — 50/50 white | Deep Forest */
.compare-panels { display: grid; grid-template-columns: 1fr 1fr;
  position: absolute; inset: 0; }
.compare-panel { padding: var(--pad-y) 72px; display: flex; flex-direction: column; }
.compare-panel[data-side="light"] { background: var(--white); color: var(--charcoal); }
.compare-panel[data-side="dark"]  { background: var(--forest); color: var(--text-body-dark); }
.compare-panel .panel-label {
  font-family: var(--font-display); font-weight: var(--fw-800); font-size: 54px;
  color: var(--forest); margin-bottom: 30px; letter-spacing: -0.02em; }
.compare-panel[data-side="dark"] .panel-label { color: var(--white); }
.panel-list > li { font-family: var(--font-body); font-size: 30px; line-height: 1.4;
  padding-left: 34px; position: relative; margin-bottom: 22px; }
.panel-list > li::before { content: ""; position: absolute; left: 0; top: 15px;
  width: 11px; height: 11px; border-radius: 50%; background: var(--green); }

/* Statement slide (§4.5) — centered giant line on Deep Forest */
.statement { display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; flex: 1 1 auto; }
.statement .statement-text {
  font-family: var(--font-display); font-weight: var(--fw-900); font-size: 92px;
  line-height: 1.02; letter-spacing: -0.02em; color: var(--white); max-width: 1500px; text-wrap: balance; }
.statement .accent-bar { margin-top: 44px; }

/* Bullet lists on content slides */
.points { display: flex; flex-direction: column; gap: 26px; }
.points > li { position: relative; padding-left: 40px;
  font-family: var(--font-body); font-size: var(--fs-body); line-height: 1.4; }
.points > li::before { content: ""; position: absolute; left: 0; top: 15px;
  width: 12px; height: 12px; border-radius: 50%; background: var(--green); }
.points > li strong { font-weight: var(--fw-800); color: inherit; }
.slide[data-bg="white"] .points > li strong, .slide[data-bg="mist"] .points > li strong { color: var(--forest); }

/* Do / Don't marker lists (mistakes) — no red, no emoji: green + / charcoal × */
.marker-list { display: flex; flex-direction: column; gap: 20px; }
.marker-list > li { display: flex; gap: 22px; align-items: flex-start;
  font-family: var(--font-body); font-size: var(--fs-body-s); line-height: 1.25; }
.marker { flex: none; width: 40px; height: 40px; display: grid; place-items: center; border-radius: 50%;
  font-family: var(--font-display); font-weight: var(--fw-900); font-size: 24px; color: var(--white); }
.marker[data-tone="do"]   { background: var(--sage); }
.marker[data-tone="dont"] { background: var(--charcoal); }
.marker-cols { display: grid; grid-template-columns: 1fr 1fr; gap: 26px 64px; }

/* Callout bar (§4 accent device) */
.callout { background: var(--green); color: var(--forest); padding: 22px 40px; border-radius: 14px;
  font-family: var(--font-display); font-weight: var(--fw-700); font-size: 32px; }

/* Contact block (opening + wrap) */
.contact { display: flex; flex-direction: column; gap: 16px; }
.contact li { display: flex; align-items: baseline; gap: 18px;
  font-family: var(--font-body); font-size: 34px; }
.contact .c-label { font-family: var(--font-display); font-weight: var(--fw-700);
  font-size: 22px; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--sage); min-width: 130px; }
.slide[data-bg="dark"] .contact .c-label { color: var(--green); }

.btn-row { display: flex; gap: 22px; flex-wrap: wrap; }
.btn { display: inline-flex; align-items: center; min-height: 64px; padding: 18px 40px;
  font-family: var(--font-display); font-weight: var(--fw-800); font-size: 26px;
  letter-spacing: 0.04em; text-transform: uppercase; text-decoration: none; border-radius: 12px; }
.btn--primary { background: var(--green); color: var(--forest); }
.btn--ghost { background: transparent; color: var(--white); box-shadow: inset 0 0 0 3px rgba(255,255,255,0.6); }
.btn--ghost.on-light { color: var(--forest); box-shadow: inset 0 0 0 3px var(--forest); }
.btn:hover { transform: translateY(-2px); }
.btn small { display: block; font-size: 14px; opacity: 0.8; margin-left: 12px; }

/* Slide-level actions bar (pull-up graphics + PDF downloads) */
.slide-actions {
  flex: none;
  display: flex; gap: 18px; flex-wrap: wrap;
  margin-top: 30px;
}
.btn--sm {
  min-height: 54px; padding: 13px 30px;
  font-size: 19px; letter-spacing: 0.05em;
  border: none; cursor: pointer;
}
.btn--sm.btn--ghost { box-shadow: inset 0 0 0 3px rgba(255,255,255,0.55); }
.btn--sm.btn--ghost.on-light { box-shadow: inset 0 0 0 3px rgba(12,51,53,0.6); }
.btn-ico { display: inline-flex; margin-right: 12px; font-size: 20px; line-height: 1; }

/* ---------------------------------------------------------------------------
   PER-SLIDE GRAPHICS CONTROL — subtle top-right icon → menu of this slide's
   graphics. Viewers can open them; the presenter drives.
   ------------------------------------------------------------------------ */
.slide-graphics { position: absolute; top: 38px; right: 46px; z-index: 6; }
.sg-btn {
  width: 46px; height: 46px; display: grid; place-items: center;
  border: none; cursor: pointer; border-radius: 13px;
  background: rgba(255,255,255,0.10); color: rgba(255,255,255,0.66);
  transition: background var(--dur-fast) var(--ease-out), color var(--dur-fast) var(--ease-out);
}
.sg-btn svg { fill: currentColor; }
.sg-btn:hover, .slide-graphics.is-open .sg-btn { background: var(--green); color: var(--forest); }
.slide[data-bg="white"] .sg-btn, .slide[data-bg="mist"] .sg-btn {
  background: rgba(12,51,53,0.06); color: rgba(12,51,53,0.45);
}
.slide[data-bg="white"] .sg-btn:hover, .slide[data-bg="mist"] .sg-btn:hover,
.slide[data-bg="white"] .slide-graphics.is-open .sg-btn,
.slide[data-bg="mist"] .slide-graphics.is-open .sg-btn { background: var(--green); color: var(--forest); }

.sg-menu {
  position: absolute; top: 58px; right: 0; min-width: 340px; max-width: 480px;
  background: #fff; border-radius: 16px; padding: 12px;
  box-shadow: 0 26px 64px rgba(8,28,29,0.30);
}
.sg-menu-label {
  font-family: var(--font-display); font-weight: var(--fw-800); font-size: 15px;
  letter-spacing: 0.16em; text-transform: uppercase; color: var(--sage);
  padding: 8px 14px 12px;
}
.sg-item {
  display: block; width: 100%; text-align: left; border: none; cursor: pointer;
  background: transparent; border-radius: 11px; padding: 15px 16px;
  font-family: var(--font-body); font-size: 21px; line-height: 1.25; color: var(--forest);
  transition: background var(--dur-fast) var(--ease-out);
}
.sg-item + .sg-item { margin-top: 2px; }
.sg-item:hover { background: var(--mist); }

/* On-slide calculator icon (mortgage / buydown) — same footprint as .sg-btn */
.slide-calc { position: absolute; top: 38px; right: 46px; z-index: 6; }

/* ---------------------------------------------------------------------------
   INTERACTIVE DIAGRAM SLIDE (the SVG is the slide; nodes open popouts)
   ------------------------------------------------------------------------ */
.web-slot { flex: 1 1 auto; min-height: 0; display: flex; }
.web-slot svg { width: 100%; height: 100%; display: block; }
.web-slot .pn { cursor: pointer; }
.web-slot .pn rect { transition: filter var(--dur-fast) var(--ease-out); }
.web-slot .pn:hover rect { filter: brightness(1.4); }
.web-fallback { color: #fff; margin: auto; font-size: 28px; }

/* ============================================================================
   SLIDE-SPECIFIC LAYOUT STYLING (Ridgeline)
   ========================================================================= */

/* Split photo panels */
.split-photo { position: relative; }
.split[data-ratio="photo-right"] .split-copy { padding-right: 72px; justify-content: center; }
.split[data-ratio="1-1"] .split-copy { justify-content: center; }

/* Figures */
.figure-wrap { display: flex; align-items: center; justify-content: center; }
.figure-wrap > svg { width: 100%; height: auto; }

/* Payment breakdown — clean stacked bar + legend chips (no leader lines) */
.pay-bar { width: 100%; height: 84px; border-radius: 12px; overflow: hidden; }
.pay-bar svg { width: 100%; height: 100%; display: block; }
.pay-legend { display: flex; flex-wrap: wrap; gap: 14px 40px; margin-top: 20px; }
.pay-chip { display: flex; align-items: center; gap: 12px;
  font-family: var(--font-display); font-weight: var(--fw-700); font-size: 24px; color: var(--charcoal); }
.pay-sw { width: 22px; height: 22px; flex: none; border-radius: 5px; }

/* Two-column locked / moves + can / cannot */
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; }
.col-head {
  font-family: var(--font-display); font-weight: var(--fw-800); font-size: 30px;
  color: var(--forest); padding-bottom: 14px; margin-bottom: 18px;
  border-bottom: 3px solid var(--card-border-light);
}
.slide[data-bg="dark"] .col-head { color: #fff; }
.col-head--lock { border-bottom-color: var(--sage); }
.col-head--move { border-bottom-color: var(--green); }
.mini-list > li {
  position: relative; padding-left: 32px; margin-bottom: 14px;
  font-family: var(--font-body); font-size: var(--fs-body-s); line-height: 1.3;
}
.mini-list > li::before { content: ""; position: absolute; left: 0; top: 13px;
  width: 11px; height: 11px; border-radius: 50%; background: var(--green); }

/* Dense slides — tighten so diagram + columns + points clear the footer */
#slide-budget-payment .slide-body { gap: 22px; }
#slide-budget-payment .slide-header,
#slide-cash-makeup .slide-header { margin-bottom: 24px; }
#slide-budget-payment .two-col { gap: 48px; }
#slide-budget-payment .mini-list > li { font-size: 24px; margin-bottom: 10px; }
#slide-budget-payment .col-head { font-size: 26px; padding-bottom: 10px; margin-bottom: 12px; }
/* The three explainers become a compact 3-across row, not full-width bullets */
#slide-budget-payment .points {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 34px;
}
#slide-budget-payment .points > li { font-size: 23px; line-height: 1.3; padding-left: 26px; }
#slide-budget-payment .points > li::before { top: 9px; width: 10px; height: 10px; }
#slide-cash-makeup .points > li { font-size: var(--fs-body-s); }

/* Opening / wrap — trim so the contact block clears the footer */
#slide-opening .headline { font-size: 84px !important; }
#slide-opening .contact { gap: 10px; margin-top: 28px !important; }
#slide-opening .contact li { font-size: 30px; }

/* Compare-loans CTA on the closing-costs/APR slide */
.compare-cta {
  align-self: flex-start; margin-top: 34px;
  display: inline-flex; align-items: center; gap: 14px;
  padding: 18px 34px; background: var(--green); color: var(--forest);
  font-family: var(--font-display); font-weight: var(--fw-800); font-size: 26px;
  letter-spacing: 0.01em; transition: transform var(--dur-fast) var(--ease-out);
}
.compare-cta:hover { transform: translateY(-2px); }

/* Do / Don't handout — client wants the red/green from the printed handout.
   Scoped to these two slides so the rest of the deck keeps the Ridgeline system. */
#slide-mistakes-donts .headline { color: var(--red); }
#slide-mistakes-donts .marker[data-tone="dont"] { background: var(--red); }
#slide-mistakes-donts .slide-header .accent-bar { background: var(--red); }
#slide-mistakes-dos .headline { color: var(--do-green); }
#slide-mistakes-dos .marker[data-tone="do"] { background: var(--do-green); }
#slide-mistakes-dos .slide-header .accent-bar { background: var(--do-green); }

/* Questions */
#slide-questions .slide-header { margin-bottom: 30px; }
.qa-list { display: flex; flex-direction: column; gap: 20px; max-width: 1500px; }
.qa { display: flex; gap: 30px; align-items: baseline; }
.qa-num {
  flex: none; width: 56px; height: 56px; display: grid; place-items: center; border-radius: 50%;
  background: var(--green); color: var(--forest);
  font-family: var(--font-display); font-weight: var(--fw-900); font-size: 28px;
}
.qa-q { font-family: var(--font-display); font-weight: var(--fw-800); font-size: 34px;
  color: #fff; line-height: 1.15; }
.slide[data-bg="white"] .qa-q, .slide[data-bg="mist"] .qa-q { color: var(--forest); }
.qa-a { font-family: var(--font-body); font-size: 24px; line-height: 1.35;
  color: var(--text-body-dark); margin-top: 6px; max-width: 1360px; }
.slide[data-bg="white"] .qa-a, .slide[data-bg="mist"] .qa-a { color: var(--charcoal); }

/* Clickable contact lines (opening / wrap) */
.contact a { color: inherit; text-decoration: none; border-bottom: 1px solid rgba(255,255,255,0.28); }
.contact a:hover { color: var(--green); border-bottom-color: var(--green); }
.wrap-qr-cap { margin-top: 16px; text-align: center; font-family: var(--font-body);
  font-size: 22px; color: var(--text-body-dark); }

/* "Closing costs vs. prepaid items" slide */
.prepaid-body { flex-direction: row; gap: 56px; align-items: stretch; }
.prepaid-copy { flex: 1 1 0; min-width: 0; display: flex; flex-direction: column; }
.prepaid-def { margin-bottom: 24px; }
.prepaid-def-head { font-family: var(--font-display); font-weight: var(--fw-800);
  font-size: 32px; color: var(--forest); margin-bottom: 6px; }
.prepaid-def-body { font-size: 25px; line-height: 1.4; color: var(--charcoal); max-width: 760px; }
.prepaid-upfront-label { font-family: var(--font-display); font-weight: var(--fw-800);
  font-size: 22px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--sage); margin: 6px 0 14px; }
.prepaid-upfront { display: flex; flex-wrap: wrap; gap: 12px 14px; margin-bottom: 26px; }
.prepaid-upfront li { display: inline-flex; align-items: center; padding: 9px 20px; border-radius: 999px;
  background: var(--mist); font-family: var(--font-display); font-weight: var(--fw-700); font-size: 23px; color: var(--forest); }
.prepaid-note { margin-top: auto; padding: 20px 26px; border-radius: 12px;
  border-left: 6px solid var(--green); background: var(--mist);
  font-size: 23px; line-height: 1.4; color: var(--charcoal); font-style: italic; }
.prepaid-figure { flex: 0 0 42%; display: flex; flex-direction: column; align-items: center;
  justify-content: center; margin: 0; padding: 0; border: 0; background: none; cursor: pointer;
  font: inherit; color: inherit; transition: transform var(--dur-fast) var(--ease-out); }
.prepaid-figure:hover { transform: translateY(-3px); }
.prepaid-figure img { max-width: 100%; max-height: 560px; object-fit: contain;
  border: 1px solid var(--card-border-light); border-radius: 12px; box-shadow: 0 10px 34px rgba(12,51,53,0.14);
  transition: box-shadow var(--dur-fast) var(--ease-out); }
.prepaid-figure:hover img { box-shadow: 0 16px 44px rgba(12,51,53,0.22); }
.prepaid-figure figcaption { margin-top: 14px; font-size: 19px; color: var(--text-meta-light);
  display: flex; align-items: center; gap: 12px; }
.prepaid-zoom { font-family: var(--font-display); font-weight: var(--fw-700); font-size: 16px;
  color: var(--sage); padding: 4px 12px; border-radius: 999px; background: var(--mist); }

/* Opening portrait — keep the top of the head in frame */
#slide-opening .photo img { object-position: center top; }

/* Wrap QR */
.wrap-qr { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.wrap-qr .photo { position: relative; inset: auto; width: 420px; height: 420px;
  margin-left: auto; background: #fff; }
.wrap-qr .photo img { object-fit: contain; padding: 24px; }
.wrap-qr .photo .wash { display: none; }
.wrap-qr .photo-placeholder { position: absolute; inset: 0; }

.calculator-overlay {
  position: fixed;
  inset: 0;
  z-index: 90;
  background: rgba(7, 31, 32, .58);
  font-family: var(--font-body);
}

.calculator-overlay[hidden] { display: none; }

.calculator-panel {
  position: fixed;
  overflow: visible;
  color: var(--charcoal);
  background: transparent;
}

.calculator-canvas {
  position: relative;
  width: 560px;
  height: 820px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transform-origin: top left;
  background: var(--forest);
  border-radius: 12px;
  box-shadow: 0 0 0 2px rgba(255, 255, 255, .2), 0 22px 70px rgba(0, 0, 0, .4);
}

.calculator-dragbar {
  min-height: 48px;
  flex: none;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 54px 7px 17px;
  color: var(--white);
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.calculator-grip { display: grid; gap: 3px; }
.calculator-grip i { width: 20px; height: 2px; background: rgba(255, 255, 255, .42); }
.calculator-drag-label { flex: 1 1 auto; font-family: var(--font-display); font-size: 13px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; }
.calculator-close { position: absolute; z-index: 2; top: 7px; right: 8px; width: 36px; height: 36px; border: 1px solid rgba(255,255,255,.3); border-radius: 50%; color: var(--white); font-size: 22px; line-height: 1; }
.calculator-close:hover { background: rgba(255, 255, 255, .12); }

.calculator-scroll { flex: none; min-height: 0; overflow: visible; padding: 0 16px 16px; }
.calculator-card { padding: 24px; background: var(--white); border-radius: 8px; }
.calculator-card h1 { margin: 0; color: var(--forest); font: 800 30px/1.1 var(--font-display); letter-spacing: -.02em; }
.calculator-disclosure { margin: 6px 0 20px; color: #68736e; font-size: 13px; }

.calculator-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.calculator-span-two { grid-column: span 2; }
.calculator-group { min-width: 0; display: grid; gap: 6px; }
.calculator-label { color: var(--forest); font: 700 13px/1.3 var(--font-display); }
.calculator-field { min-height: 43px; display: flex; align-items: center; padding: 0 11px; border: 1px solid #dbe3de; border-radius: 5px; background: #fbfcfb; color: #839087; }
.calculator-field:focus-within { border-color: var(--green); box-shadow: 0 0 0 2px rgba(140, 198, 62, .18); }
.calculator-field input { width: 100%; min-width: 0; padding: 10px 5px; border: 0; outline: 0; color: var(--charcoal); background: transparent; font: 600 17px/1.2 var(--font-body); }
.calculator-help { margin: -5px 0 1px; color: #68736e; font-size: 12px; }
.calculator-terms { display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; }
.calculator-terms button { min-height: 42px; border: 1px solid #dbe3de; border-radius: 5px; color: var(--forest); background: #f7f9f7; font-weight: 700; }
.calculator-terms button.is-selected { color: var(--white); background: var(--forest); border-color: var(--forest); }

.calculator-toggle { width: 100%; display: flex; justify-content: space-between; margin: 18px 0 14px; padding: 11px 0; border-block: 1px solid #e5ebe7; color: var(--forest); font-weight: 700; text-align: left; }
.calculator-advanced { margin-bottom: 17px; }
.calculator-advanced[hidden] { display: none; }
.calculator-result { padding: 18px; color: var(--white); background: var(--forest); border-left: 6px solid var(--green); }
.calculator-result-label { margin: 0; color: rgba(255,255,255,.72); font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.calculator-total { margin: 1px 0 12px; font: 900 42px/1 var(--font-display); }
.calculator-breakdown { display: grid; gap: 5px; padding-top: 11px; border-top: 1px solid rgba(255,255,255,.18); }
.calculator-breakdown div { display: flex; justify-content: space-between; gap: 18px; font-size: 13px; }

.calculator-footer { display: flex; align-items: center; gap: 13px; padding: 13px 8px 0; color: rgba(255,255,255,.72); font-size: 11px; line-height: 1.45; }
.calculator-footer img { width: 78px; max-height: 48px; object-fit: contain; background: var(--white); }
.calculator-footer p { margin: 0; }

.calculator-resize-handle {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 32px;
  height: 32px;
  cursor: nwse-resize;
  touch-action: none;
}
.calculator-resize-handle::after { content: ''; position: absolute; right: 6px; bottom: 6px; width: 14px; height: 14px; border-right: 3px solid var(--green); border-bottom: 3px solid var(--green); }

@media (prefers-reduced-motion: reduce) {
  .calculator-panel { scroll-behavior: auto; }
}

/* Webinar Studio: the slide frame is the 1920×1080 stage. */
html, body { width: 1920px; height: 1080px; overflow: hidden; }
.slide-scaler { position: absolute; top: 0; right: auto; bottom: auto; left: 0; width: 1920px; height: 1080px; transform: none; }

