  // first-time-homebuyer/deck/js/overlay-geometry.js
  var OVERLAY_MARGIN = 16;
  var OVERLAY_MIN_SCALE = 0.35;
  var positive = (value, fallback) => Number.isFinite(value) && value > 0 ? value : fallback;
  var scaleLimit = (value) => Math.min(1, positive(value, 1));
  var available = (extent, margin) => Math.max(Number.EPSILON, extent - 2 * margin);
  var requiredDimension = (value, fallback, name) => {
    const resolved = positive(value, fallback);
    if (!Number.isFinite(resolved) || resolved <= 0) throw new RangeError(`Invalid ${name}`);
    return resolved;
  };
  var between = (value, low, high) => Math.min(Math.max(value, low), high);
  var size = (o) => {
    const intrinsicWidth = requiredDimension(o.intrinsicWidth, o.fallbackWidth, "intrinsic width");
    const intrinsicHeight = requiredDimension(o.intrinsicHeight, o.fallbackHeight, "intrinsic height");
    const requestedMargin = Math.max(0, Number.isFinite(o.margin) ? o.margin : OVERLAY_MARGIN);
    const viewportWidth = positive(o.viewportWidth, intrinsicWidth + 2 * requestedMargin);
    const viewportHeight = positive(o.viewportHeight, intrinsicHeight + 2 * requestedMargin);
    const margin = Math.min(
      requestedMargin,
      Math.max(0, (viewportWidth - 1) / 2),
      Math.max(0, (viewportHeight - 1) / 2)
    );
    return {
      intrinsicWidth,
      intrinsicHeight,
      margin,
      viewportWidth,
      viewportHeight
    };
  };
  var result = (d, scale, left, top) => ({
    intrinsicWidth: d.intrinsicWidth,
    intrinsicHeight: d.intrinsicHeight,
    scale,
    width: d.intrinsicWidth * scale,
    height: d.intrinsicHeight * scale,
    left,
    top
  });
  function fitOverlay(options) {
    const d = size(options);
    const scale = Math.min(
      scaleLimit(options.maxScale),
      available(d.viewportWidth, d.margin) / d.intrinsicWidth,
      available(d.viewportHeight, d.margin) / d.intrinsicHeight
    );
    const width = d.intrinsicWidth * scale;
    const height = d.intrinsicHeight * scale;
    return result(
      d,
      scale,
      Math.max(d.margin, (d.viewportWidth - width) / 2),
      Math.max(d.margin, (d.viewportHeight - height) / 2)
    );
  }
  function clampOverlay(options) {
    const d = size(options);
    const scale = Math.min(
      scaleLimit(options.scale),
      available(d.viewportWidth, d.margin) / d.intrinsicWidth,
      available(d.viewportHeight, d.margin) / d.intrinsicHeight
    );
    const width = d.intrinsicWidth * scale;
    const height = d.intrinsicHeight * scale;
    return result(
      d,
      scale,
      between(Number.isFinite(options.left) ? options.left : d.margin, d.margin, d.viewportWidth - d.margin - width),
      between(Number.isFinite(options.top) ? options.top : d.margin, d.margin, d.viewportHeight - d.margin - height)
    );
  }
  function resizeOverlay(options) {
    const d = size(options);
    const left = Math.max(d.margin, Number.isFinite(options.left) ? options.left : d.margin);
    const top = Math.max(d.margin, Number.isFinite(options.top) ? options.top : d.margin);
    const dx = Number.isFinite(options.deltaX) ? options.deltaX : 0;
    const dy = Number.isFinite(options.deltaY) ? options.deltaY : 0;
    const delta = (dx * d.intrinsicWidth + dy * d.intrinsicHeight) / (d.intrinsicWidth ** 2 + d.intrinsicHeight ** 2);
    const maximum = Math.min(
      1,
      Math.max(Number.EPSILON, d.viewportWidth - d.margin - left) / d.intrinsicWidth,
      Math.max(Number.EPSILON, d.viewportHeight - d.margin - top) / d.intrinsicHeight
    );
    const scale = between(scaleLimit(options.startScale) + delta, Math.min(OVERLAY_MIN_SCALE, maximum), maximum);
    return result(d, scale, left, top);
  }

  // first-time-homebuyer/deck/js/surface-fit.js
  var finiteSize = (value, fallback) => Number.isFinite(value) && value > 0 ? value : fallback;
  function createSurfaceController({
    viewport,
    shell: shell2,
    surface: surface2,
    getDesignSize,
    margin = OVERLAY_MARGIN
  }) {
    let active = false;
    let geometry = null;
    let preferredScale = 1;
    let userPositioned = false;
    let frame = 0;
    let destroyed = false;
    let generation = 0;
    const viewportSize = () => ({
      viewportWidth: finiteSize(viewport.clientWidth, document.documentElement.clientWidth),
      viewportHeight: finiteSize(viewport.clientHeight, document.documentElement.clientHeight)
    });
    const dimensions = () => {
      const { width, height } = getDesignSize();
      return {
        intrinsicWidth: width,
        intrinsicHeight: height,
        fallbackWidth: width,
        fallbackHeight: height,
        margin,
        ...viewportSize()
      };
    };
    const apply = (next) => {
      geometry = next;
      Object.assign(shell2.style, {
        width: `${next.width}px`,
        height: `${next.height}px`,
        left: `${next.left}px`,
        top: `${next.top}px`
      });
      Object.assign(surface2.style, {
        width: `${next.intrinsicWidth}px`,
        height: `${next.intrinsicHeight}px`,
        transformOrigin: "top left",
        transform: `scale(${next.scale})`
      });
      return next;
    };
    const fit = () => {
      if (destroyed || !active) return geometry;
      const options = dimensions();
      if (!geometry || !userPositioned) {
        return apply(fitOverlay({ ...options, maxScale: preferredScale }));
      }
      return apply(clampOverlay({
        ...options,
        scale: preferredScale,
        left: geometry.left,
        top: geometry.top
      }));
    };
    const scheduleFit = () => {
      if (destroyed || !active) return;
      cancelAnimationFrame(frame);
      const token = ++generation;
      frame = requestAnimationFrame(() => {
        frame = 0;
        if (!destroyed && active && token === generation) fit();
      });
    };
    const reset = () => {
      generation += 1;
      cancelAnimationFrame(frame);
      frame = 0;
      preferredScale = 1;
      userPositioned = false;
      geometry = null;
    };
    const moveFrom = (start, deltaX, deltaY) => {
      if (destroyed || !active || !start) return geometry;
      userPositioned = true;
      return apply(clampOverlay({
        ...dimensions(),
        scale: preferredScale,
        left: start.left + deltaX,
        top: start.top + deltaY
      }));
    };
    const resizeFrom = (start, deltaX, deltaY) => {
      if (destroyed || !active || !start) return geometry;
      const next = resizeOverlay({
        ...dimensions(),
        startScale: start.scale,
        left: start.left,
        top: start.top,
        deltaX,
        deltaY
      });
      preferredScale = next.scale;
      userPositioned = true;
      return apply(next);
    };
    const observer = new ResizeObserver(scheduleFit);
    observer.observe(viewport);
    window.addEventListener("resize", scheduleFit);
    return {
      setActive(next) {
        if (destroyed) return;
        active = Boolean(next);
        generation += 1;
        cancelAnimationFrame(frame);
        frame = 0;
        if (active) scheduleFit();
      },
      fit,
      reset,
      moveFrom,
      resizeFrom,
      scheduleFit,
      getGeometry: () => geometry,
      destroy() {
        destroyed = true;
        active = false;
        generation += 1;
        cancelAnimationFrame(frame);
        frame = 0;
        observer.disconnect();
        window.removeEventListener("resize", scheduleFit);
      }
    };
  }

