  var OVERLAY_MARGIN = 16;
  var OVERLAY_MIN_SCALE = 0.35;
  var positive = (value, fallback) => Number.isFinite(value) && value > 0 ? value : fallback;
  var scaleLimit = (value) => Math.min(1, positive(value, 1));
  var available = (extent, margin) => Math.max(Number.EPSILON, extent - 2 * margin);
  var requiredDimension = (value, fallback, name) => {
    const resolved = positive(value, fallback);
    if (!Number.isFinite(resolved) || resolved <= 0) throw new RangeError(`Invalid ${name}`);
    return resolved;
  };
  var between = (value, low, high) => Math.min(Math.max(value, low), high);
  var size = (o) => {
    const intrinsicWidth = requiredDimension(o.intrinsicWidth, o.fallbackWidth, "intrinsic width");
    const intrinsicHeight = requiredDimension(o.intrinsicHeight, o.fallbackHeight, "intrinsic height");
    const requestedMargin = Math.max(0, Number.isFinite(o.margin) ? o.margin : OVERLAY_MARGIN);
    const viewportWidth = positive(o.viewportWidth, intrinsicWidth + 2 * requestedMargin);
    const viewportHeight = positive(o.viewportHeight, intrinsicHeight + 2 * requestedMargin);
    const margin = Math.min(
      requestedMargin,
      Math.max(0, (viewportWidth - 1) / 2),
      Math.max(0, (viewportHeight - 1) / 2)
    );
    return {
      intrinsicWidth,
      intrinsicHeight,
      margin,
      viewportWidth,
      viewportHeight
    };
  };
  var result = (d, scale, left, top) => ({
    intrinsicWidth: d.intrinsicWidth,
    intrinsicHeight: d.intrinsicHeight,
    scale,
    width: d.intrinsicWidth * scale,
    height: d.intrinsicHeight * scale,
    left,
    top
