    let body = "";
    if (d.intro) body += `<p class="modal-intro">${d.intro}</p>`;
    if (d.table) body += renderTable(d.table);
    if (d.sections) body += d.sections.map(section).join("");
    bodyEl.innerHTML = body;
    const lines = (d.compliance || []).map((k) => COMPLIANCE[k]).filter(Boolean);
    if (lines.length) {
      footEl.textContent = lines.join("  ");
      footEl.hidden = false;
    } else footEl.hidden = true;
    fitController.setActive(false);
    surface.classList.remove("modal--media");
    root.classList.remove("is-visible");
    root.classList.add("is-open", "is-measuring");
    isOpen = true;
    activeKind = "content";
    const token = ++openToken;
    document.body.classList.add("modal-open");
    return fitEducational(d, token);
  }
  async function openMedia(id, opener) {
    const item = mediaById(id);
    if (!item) {
      console.warn(`[deck] no presenter media "${id}"`);
      return false;
    }
    rememberSessionOpener(opener);
    headEl.innerHTML = `<h2 class="modal-title" id="modal-title">${item.title}</h2>`;
    bodyEl.innerHTML = `
    <div class="modal-media-frame">
      <img src="${item.src}" alt="${item.alt}">
      <p class="modal-media-error" hidden>Graph unavailable</p>
    </div>`;
    const image = bodyEl.querySelector("img");
    const error = bodyEl.querySelector(".modal-media-error");
    footEl.hidden = true;
    fitController.setActive(false);
    surface.classList.add("modal--media");
    root.classList.remove("is-visible");
    root.classList.add("is-open", "is-measuring");
    isOpen = true;
    activeKind = "media";
    const token = ++openToken;
    document.body.classList.add("modal-open");
    try {
      await image.decode();
      if (!isOpen || token !== openToken || activeKind !== "media") return false;
      currentDesignSize = {
        width: image.naturalWidth,
        height: image.naturalHeight + MEDIA_TOOLBAR_HEIGHT
      };
    } catch {
      if (!isOpen || token !== openToken || activeKind !== "media") return false;
      image.hidden = true;
      error.hidden = false;
      currentDesignSize = MEDIA_FALLBACK;
    }
    fitController.reset();
    fitController.setActive(true);
    fitController.fit();
    return revealAndFocus("media", token);
  }
  function clearFitGeometry() {
    Object.assign(shell.style, { width: "", height: "", left: "", top: "" });
    Object.assign(surface.style, { width: "", height: "", transform: "", transformOrigin: "" });
  }
  function closeModal() {
    if (!isOpen) return;
    isOpen = false;
    const token = ++openToken;
    fitController.setActive(false);
    root.classList.remove("is-visible");
    document.body.classList.remove("modal-open");
    const done = () => {
      if (isOpen || token !== openToken) return;
      root.classList.remove("is-open", "is-measuring");
      if (lastFocused && document.contains(lastFocused)) lastFocused.focus();
      clearFitGeometry();
      lastFocused = null;
      activeKind = null;
    };
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) done();
    else setTimeout(done, 200);
  }
  function isModalOpen() {
    return isOpen;
  }

  // tools/studio-export/runtime/overlays.js
  var report2 = (id) => {
    try {
      window.msfgRuntime.emit("supported-overlay-state", { actionId: id });
    } catch {
    }
  };
  function startOverlays({ modal, modalIds = [], mediaIds = [] }) {
    const openers = new Map([
      ...modalIds.map((id) => [id, modal.openModal]),
      ...mediaIds.map((id) => [id, modal.openMedia])
    ]);
    let openId = null;
    modal.initModal();
    const root2 = document.getElementById("modal-root");
    new MutationObserver(() => {
      if (!openId || modal.isModalOpen()) return;
      const closed = openId;
      openId = null;
      report2(closed);
    }).observe(root2, { attributes: true, attributeFilter: ["class"] });
    const open = (id, opener) => {
      const show = openers.get(id);
      if (!show) return;
      if (openId === id && modal.isModalOpen()) return;
      if (openId) report2(openId);
      openId = id;
      report2(id);
      Promise.resolve(show(id, opener)).catch(() => {
      });
    };
    document.addEventListener("click", (event) => {
      const trigger = event.target instanceof Element ? event.target.closest("[data-modal], [data-media]") : null;
      if (trigger) open(trigger.dataset.modal || trigger.dataset.media, trigger);
    });
    window.addEventListener("msfg:supported-overlay-state", (event) => {
      const id = event.detail && event.detail.actionId;
      if (typeof id !== "string") return;
      if (openId === id && modal.isModalOpen()) modal.closeModal();
      else open(id);
    });
    window.addEventListener("msfg:slide-exit", () => {
      if (modal.isModalOpen()) modal.closeModal();
    });
  }

  // tools/studio-export/runtime/studio-slide-entry.js
  startBuilds();
  startOverlays({ modal: modal_exports, modalIds: Object.keys(MODALS) });
})();

(() => {
  // tools/studio-export/runtime/builds.js
  var report = (type, payload) => {
    try {
      window.msfgRuntime.emit(type, payload);
    } catch {
    }
  };
  function startBuilds() {
    const slide = document.querySelector(".slide");
    const items = slide ? [...slide.querySelectorAll(".build")] : [];
    const total = items.length;
    let revealed = 0;
    let playing = false;
    let timers = [];
    const emitState = () => report("animation-state", { current: revealed, total, playing });
    const clearTimers = () => {
      timers.forEach((timer) => clearTimeout(timer));
      timers = [];
    };
    const reveal = (count) => {
      const next = Math.max(0, Math.min(total, count));
      items.forEach((item, index) => item.classList.toggle("is-in", index < next));
      revealed = next;
      emitState();
    };
    const pause = () => {
      clearTimers();
      playing = false;
      emitState();
    };
    const step = (delta) => {
      clearTimers();
      playing = false;
      reveal(revealed + delta);
    };
    const play = () => {
      clearTimers();
      if (!total) {
        playing = false;
        emitState();
        return;
      }
      if (revealed >= total) reveal(0);
      const start = revealed;
      playing = true;
      emitState();
      items.slice(start).forEach((item, offset) => {
        const target = start + offset + 1;
        timers.push(setTimeout(() => {
          if (!playing) return;
          item.classList.add("is-in");
          revealed = target;
          if (target === total) {
            playing = false;
            timers = [];
          }
          emitState();
        }, 60 + Math.min(offset, 6) * 90));
      });
    };
    const run = () => {
      clearTimers();
      revealed = 0;
      playing = false;
      items.forEach((item) => item.classList.remove("is-in"));
      play();
    };
    window.addEventListener("msfg:slide-enter", run);
    window.addEventListener("msfg:slide-exit", clearTimers);
    window.addEventListener("msfg:animation-forward", () => step(1));
    window.addEventListener("msfg:animation-back", () => step(-1));
    window.addEventListener("msfg:animation-play", play);
    window.addEventListener("msfg:animation-pause", pause);
    run();
  }

  // tools/studio-export/runtime/studio-slide-entry.js
  startBuilds();
})();

